from itertools import combinations
G={
'3': ([(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==3],[(2,1),(4,5),(5,1),(6,4)]),
'8': ([(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8],[(3,17),(4,16),(5,15),(7,15)]),
'4': ([(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==4],[(8,11),(9,15),(10,10),(14,14)]),
'7': ([(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==7],[(12,5),(17,5)]),
'6': ([(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==6],[(18,11),(19,16),(22,16),(23,11)]),
'1a': ([(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1 and r<=12],[(10,24),(12,24)]),
'1b': ([(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1 and r>=16],[(16,20),(21,20),(22,24),(23,23)])}
# Find pairwise deltas applying second component B, with >=2 marker overlap, shape overlap count
for a,b in combinations(G,2):
    ac,ap=G[a]; bc,bp=G[b]
    poss={}
    for pa,pb in combinations(ap,2):
        va=(pb[0]-pa[0],pb[1]-pa[1])
        for qa,qb in combinations(bp,2):
            vb=(qb[0]-qa[0],qb[1]-qa[1])
            if va==vb:
                d=(pa[0]-qa[0],pa[1]-qa[1])
                poss[d]=len({(r+d[0],c+d[1]) for r,c in bp}&set(ap))
    for d,n in sorted(poss.items(), key=lambda x:-x[1]):
        ov=len(set(ac)&{(r+d[0],c+d[1]) for r,c in bc})
        print(a,b,'moveB',d,'pins overlap',n,'shape overlap',ov)

