# refresh relevant group data
G['1a']= ([(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1 and r<=12],[(10,24),(12,24)])
G['1b']= ([(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1 and r>=16],[(16,22),(21,21),(22,25),(23,24)])
for a,b in combinations(G,2):
    ac,ap=G[a]; bc,bp=G[b]; poss={}
    for pa,pb in combinations(ap,2):
        va=(pb[0]-pa[0],pb[1]-pa[1])
        for qa,qb in combinations(bp,2):
            if (qb[0]-qa[0],qb[1]-qa[1])==va:
                d=(pa[0]-qa[0],pa[1]-qa[1]); poss[d]=len({(r+d[0],c+d[1]) for r,c in bp}&set(ap))
    for d,n in poss.items():
        ov=len(set(ac)&{(r+d[0],c+d[1]) for r,c in bc})
        if n>=2: print(a,b,d,n,'overlap',ov)

